fn batches_in_interval_for_concurrent_fsync_count(interval_fsyncs: u64, concurrent_fsync_count: u64) -> u64 {
    if concurrent_fsync_count > interval_fsyncs {
        1
    } else {
        interval_fsyncs / concurrent_fsync_count
    }
}

